    if (file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s", content);
    fclose(file);

    // Set file permissions to owner read/write only
    if (chmod(path, S_IRUSR | S_IWUSR) != 0) {
        perror("chmod");
    }

    // Set file owner to current user (if not already)
    struct passwd *pw = getpwuid(geteuid());
    if (pw && chown(path, pw->pw_uid, -1) != 0) {
        perror("chown");
    }
}

