#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <sys/types.h>

void save_secrete_file(const char *directory, const char *filename, const char *content) {
    char path[1024];
    snprintf(path, sizeof(path), "%s/%s", directory, filename);

    // Check if directory exists and is writable
    struct stat st;
    if (stat(directory, &st) != 0 || !(st.st_mode & S_IWUSR)) {
        fprintf(stderr, "Directory does not exist or is not writable.\n");
        return;
    }

    FILE *file = fopen(path, "w");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    fprintf(file, "%s", content);
    fclose(file);

    // Set owner to current user (only if not already set)
    if (chown(path, getuid(), getgid()) != 0) {
        perror("Failed to set owner");
    }

    // Restrict permissions to owner only
    if (chmod(path, S_IRUSR | S_IWUSR) != 0) {
        perror("Failed to set permissions");
    }
}
